import json,hashlib
p='/workspace/scratch/volume4/batch519-528.json';d=dict(pages=[],units=[],boundary_notes=[],review_notes=[],completed=False)
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(519,[
('وطرد هذا المذهب مفسد للدنيا وللدين، بل لسائر أديان الرسل. ولهذا لما طرده قوم أسقطوا الأسباب الدنيوية وعطلوها، وجعلوا وجودها كعدمها. ولم يمكنهم ذلك، فإنهم لا بد أن يأكلوا ويشربوا، ويباشروا من الأسباب ما يدفع عنهم الحر والبرد والألم!', 'Последовательное применение этого учения губительно для земной жизни и религии, более того — для всех религий посланников. Поэтому некоторые люди, последовательно применяя его, отвергли и упразднили земные причины, приравняв их наличие к отсутствию. Но это оказалось для них невозможно: им непременно приходится есть, пить и прибегать к причинам, защищающим от жары, холода и боли!'),
('فإذا قيل لهم: هلا أسقطتم ذلك؟ قالوا: لأجل الاقتران العادي. فقيل لهم: فهلا قمتم بما أسقطتموه من الأسباب لأجل الاقتران العادي أيضا! فهذا المذهب قد فطر الله سبحانه الحيوان ـ ناطقه وأعجمه ـ على خلافه.', 'Когда им говорят: «Почему же вы не отвергнете и это?» — они отвечают: «Из-за обычного сопутствия». Им возражают: «Почему же тогда вы не прибегаете к отвергнутым вами причинам также из-за обычного сопутствия?» Пречистый Аллах создал живые существа — и говорящих, и бессловесных — с естеством, противоречащим этому учению.'),
('وقوم طردوه، فتركوا له الأسباب الأخروية، وقالوا: سبق العلم والحكم بالسعادة والشقاوة لا يتغير البتة، فسواء علينا الفعل والترك. فإن سبق العلم والحكم بالشقاوة فنحن أشقياء، عملنا أو لم نعمل. وإن سبقا بالسعادة فنحن سعداء، عملنا أو لم نعمل. ومنهم من يترك الدعاء جملة، بناء على هذا الأصل، ويقول: المدعو به إن سبق العلم والحكم بحصوله حصل، دعونا أو لم ندع. وإن سبقا بعدم حصوله لم يحصل وإن دعونا.', 'Другие последовательно применили его и оставили из-за него причины, относящиеся к Последней жизни. Они сказали: «Предшествующие знание и решение о счастье и несчастье совершенно неизменны, поэтому нам всё равно — действовать или оставлять действие. Если знание и решение предшествуют о несчастье, мы несчастны, действуем или не действуем. Если они предшествуют о счастье, мы счастливы, действуем или не действуем». Некоторые на основании этого вообще оставляют мольбу и говорят: «Если исполнение просимого предрешено знанием и решением, оно случится, молимся мы или не молимся. Если ими предрешено, что оно не случится, оно не случится, даже если мы помолимся».'),
('قال شيخنا: وهذا الأصل الفاسد مخالف للكتاب والسنة وإجماع السلف وأئمة الدين، ومخالف لصريح المعقول وللحس والمشاهدة.', 'Наш шейх сказал: «Эта порочная основа противоречит Книге, Сунне, единогласию предшественников и имамов религии, а также ясному разуму, чувственному восприятию и наблюдению».'),
('وقد سئل النبي صلى الله عليه وسلم عن إسقاط الأسباب نظرا إلى القدر؟ فرد ذلك، وألزم القيام بالأسباب، كما في «الصحيح» عنه صلى الله عليه وسلم أنه قال: «ما منكم من', 'Пророка, да благословит его Аллах и приветствует, спрашивали об отказе от причин ввиду предопределения. Он отверг это и обязал прибегать к причинам. Как передано в «Сахихе», он, да благословит его Аллах и приветствует, сказал: «Нет среди вас')])
page(520,[
('أحد إلا وقد علم مقعده من الجنة، ومقعده من النار» قالوا: يا رسول الله، أفلا ندع العمل ونتكل على الكتاب؟ فقال: «لا، اعملوا، فكل ميسر لما خلق له».', 'никого, чьё место в Раю и место в Огне не было бы известно». Они спросили: «Посланник Аллаха, почему же нам не оставить дела и не положиться на запись?» Он ответил: «Нет, действуйте, ибо каждому облегчается то, для чего он сотворён».'),
('وفي «الصحيح» أيضا أنه قيل له: يا رسول الله، أرأيت ما يكدح الناس فيه اليوم ويعملون: أمر قضي عليهم ومضى أم فيما يستقبلون مما أتاهم فيه الحجة؟ فقال: «بل شيء قضي عليهم ومضى فيهم». قالوا: يا رسول الله، أفلا ندع العمل ونتكل على كتابنا؟ فقال: «لا، اعملوا فكل ميسر لما خلق له».', 'В «Сахихе» также передано, что его спросили: «Посланник Аллаха, скажи о том, над чем люди сегодня трудятся и что совершают: это уже решённое для них и предшествовавшее или то, что им ещё предстоит, о чём к ним пришёл довод?» Он ответил: «Это уже решённое для них и предшествовавшее им». Они спросили: «Посланник Аллаха, почему же нам не оставить дела и не положиться на нашу запись?» Он ответил: «Нет, действуйте, ибо каждому облегчается то, для чего он сотворён».'),
('وفي «السنن» عنه صلى الله عليه وسلم أنه قيل له: أرأيت أدوية نتداوى بها، ورقى نسترقي بها، وتقاة نتقي بها = هل ترد من قدر الله شيئا؟ فقال: «هي من قدر الله».', 'В «Сунан» передано, что его, да благословит его Аллах и приветствует, спросили: «Скажи: лекарства, которыми мы лечимся, рукъя, с которыми обращаемся за исцелением, и защитные средства, которыми защищаемся, отводят ли что-либо из предопределения Аллаха?» Он ответил: «Они — из предопределения Аллаха».'),
('وكذلك قول عمر لأبي عبيدة، وقد قال له أبو عبيدة: أفر من قدر الله؟ ـ يعني من الطاعون ـ فقال: أفر من قدر الله إلى قدر الله.', 'Таковы и слова ‘Умара Абу ‘Убайде. Когда Абу ‘Убайда спросил его: «Бежишь от предопределения Аллаха?» — имея в виду чуму, — он ответил: «Бегу от предопределения Аллаха к предопределению Аллаха».'),
('وقد قال تعالى في السحاب: {فأنزلنا به الماء فأخرجنا به من كل الثمرات} [الأعراف: ٥٧]. وقال تعالى: {فأحيا به الأرض بعد موتها} [البقرة: ١٦٤]. وقال تعالى: {يهدي به الله من اتبع رضوانه سبل السلام} [المائدة: ١٦]. وقال تعالى: {بما كنتم تعملون} [الأعراف: ٤٣]، {بما', 'Всевышний сказал об облаках: {فأنزلنا به الماء فأخرجنا به من كل الثمرات} — «И Мы ниспослали посредством него воду и вывели ею всевозможные плоды» [7:57]. Всевышний сказал: {فأحيا به الأرض بعد موتها} — «И оживил ею землю после её смерти» [2:164]. Всевышний сказал: {يهدي به الله من اتبع رضوانه سبل السلام} — «Посредством него Аллах ведёт следующего за Его довольством путями мира» [5:16]. Всевышний сказал: {بما كنتم تعملون} — «За то, что вы совершали» [7:43], {بما')])
page(521,[
('كنتم تكسبون} [الأعراف: ٣٩]، {ذلك بما قدمت يداك} [الحج: ١٠].', 'كنتم تكسبون} — «За то, что вы приобретали» [7:39], {ذلك بما قدمت يداك} — «Это — за то, что прежде совершили твои руки» [22:10].'),
('والقرآن مملوء من ترتيب الأحكام الكونية والشرعية والثواب والعقاب على الأسباب بطرق متنوعة: فيأتي بباء السببية تارة، وباللام تارة، وبـ«أن» تارة، وبـ«كي» تارة، ويذكر الوصف المقتضي تارة. ويذكر صريح التعليل تارة كقوله: ذلك بأنهم فعلوا كذا وقالوا كذا. ويذكر الجزاء تارة كقوله: {وذلك جزاء الظالمين} [المائدة: ٢٩]، {وهل يجزى إلا الكفور} [سبأ: ١٧]. ويذكر المقتضي للحكم والمانع منه كقوله: {وما منعنا أن نرسل بالآيات إلا أن كذب بها الأولون} [الإسراء: ٥٩]. وعند منكري الأسباب والحكم لم يمنعه إلا محض مشيئته ليس إلا.', 'Коран полон различных способов связывания установлений мироздания и Закона, награды и наказания с причинами. Иногда употребляется частица «би», выражающая причину, иногда — «ли», иногда — «ан», иногда — «кай»; иногда упоминается обусловливающее свойство. Иногда причина указывается прямо, например: это — потому, что они сделали так-то и сказали так-то. Иногда упоминается воздаяние, как в словах: {وذلك جزاء الظالمين} — «Таково воздаяние несправедливым» [5:29], {وهل يجزى إلا الكفور} — «Разве так воздаётся кому-либо, кроме неблагодарного?» [34:17]. Упоминается и то, что обусловливает решение, и то, что ему препятствует, как в словах: {وما منعنا أن نرسل بالآيات إلا أن كذب بها الأولون} — «Нам помешало послать знамения лишь то, что прежние народы сочли их ложью» [17:59]. По мнению отрицающих причины и мудрые цели, ничто не препятствовало Ему, кроме одной лишь Его воли.'),
('وقال: {إن الذين آمنوا وعملوا الصالحات يهديهم ربهم بإيمانهم} [يونس: ٩]. وقال: {الر كتاب أنزلناه إليك لتخرج الناس من الظلمات إلى النور بإذن ربهم} [إبراهيم: ١]. وقال: {كلوا واشربوا هنيئا بما أسلفتم في الأيام الخالية} [الحاقة: ٢٤]. وقال: {ومن يتق الله يجعل له مخرجا ويرزقه من حيث لا يحتسب} [الطلاق: ٢ ـ ٣]، {ومن يتق الله يكفر عنه سيئاته} [الطلاق: ٥]، {ومن يتق الله يجعل له من أمره يسرا} [الطلاق: ٤]، {إن تتقوا الله يجعل لكم فرقانا} [الأنفال: ٢٩]، {وإن تصبروا وتتقوا لا يضركم كيدهم شيئا} [آل عمران: ١٢٠]. وقال: {فبظلم من الذين هادوا حرمنا عليهم طيبات أحلت لهم وبصدهم عن سبيل الله كثيرا وأخذهم الربا وقد نهوا عنه وأكلهم أموال الناس بالباطل} [النساء: ١٦٠].', 'Он сказал: {إن الذين آمنوا وعملوا الصالحات يهديهم ربهم بإيمانهم} — «Верующих и совершающих праведные дела их Господь ведёт верным путём благодаря их вере» [10:9]. Он сказал: {الر كتاب أنزلناه إليك لتخرج الناس من الظلمات إلى النور بإذن ربهم} — «Алиф. Лям. Ра. Это — Книга, которую Мы ниспослали тебе, чтобы ты вывел людей из мраков к свету с дозволения их Господа» [14:1]. Он сказал: {كلوا واشربوا هنيئا بما أسلفتم في الأيام الخالية} — «Ешьте и пейте во здравие за то, что вы совершили в минувшие дни» [69:24]. Он сказал: {ومن يتق الله يجعل له مخرجا ويرزقه من حيث لا يحتسب} — «Тому, кто боится Аллаха, Он даёт выход и наделяет уделом оттуда, откуда тот не ожидает» [65:2–3]; {ومن يتق الله يكفر عنه سيئاته} — «Кто боится Аллаха, тому Он простит дурные деяния» [65:5]; {ومن يتق الله يجعل له من أمره يسرا} — «Кто боится Аллаха, тому Он облегчит дело» [65:4]; {إن تتقوا الله يجعل لكم فرقانا} — «Если вы будете бояться Аллаха, Он дарует вам различение» [8:29]; {وإن تصبروا وتتقوا لا يضركم كيدهم شيئا} — «Если вы будете терпеливы и богобоязненны, их козни ничем вам не повредят» [3:120]. Он сказал: {فبظلم من الذين هادوا حرمنا عليهم طيبات أحلت لهم وبصدهم عن سبيل الله كثيرا وأخذهم الربا وقد نهوا عنه وأكلهم أموال الناس بالباطل} — «За несправедливость иудеев, за то, что они многих отвращали от пути Аллаха, брали рост, хотя им это было запрещено, и незаконно пожирали имущество людей, Мы запретили им блага, прежде им дозволенные» [4:160–161].')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
